package cully

import (
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

func repoRoot(t *testing.T) string {
	t.Helper()
	root, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		t.Fatal(err)
	}
	return root
}

// The committed plugin files are generated by PluginFiles. Regenerate them with
// CULLY_UPDATE_PLUGINS=1 go test ./internal/cully -run PluginFiles.
func TestPluginFilesAreCommittedAndComplete(t *testing.T) {
	root := repoRoot(t)
	files := PluginFiles()
	for path, want := range files {
		full := filepath.Join(root, path)
		if os.Getenv("CULLY_UPDATE_PLUGINS") == "1" {
			if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(full, []byte(want), 0o644); err != nil {
				t.Fatal(err)
			}
		}
		got, err := os.ReadFile(full)
		if err != nil || string(got) != want {
			t.Errorf("%s is stale or missing; run CULLY_UPDATE_PLUGINS=1 go test ./internal/cully -run PluginFiles (%v)", path, err)
		}
		if strings.HasSuffix(path, ".json") && !json.Valid([]byte(want)) {
			t.Errorf("%s is not valid JSON", path)
		}
	}
	// Nothing else may hide in the plugin directories.
	_ = filepath.WalkDir(filepath.Join(root, "plugins"), func(path string, d os.DirEntry, err error) error {
		if err == nil && !d.IsDir() {
			rel, _ := filepath.Rel(root, path)
			if _, ok := files[filepath.ToSlash(rel)]; !ok {
				t.Errorf("unexpected file in plugins: %s", rel)
			}
		}
		return nil
	})
	for _, agent := range []string{"claude", "cursor", "codex"} {
		skill, _ := os.ReadFile(filepath.Join(root, "plugins", agent, "skills", "cully", "SKILL.md"))
		if strings.TrimSpace(string(skill)) != strings.TrimSpace(cullySkill()) {
			t.Errorf("%s plugin skill differs from the canonical skill", agent)
		}
	}
}

// hookSubcommands lists "event: subcommand" for every Cully hook in a hooks
// config, ignoring the executable path, which differs between setup and a plugin.
func hookSubcommands(t *testing.T, config map[string]any) []string {
	t.Helper()
	var out []string
	events, _ := config["hooks"].(map[string]any)
	for event, groups := range events {
		for _, group := range toList(groups) {
			entry, _ := group.(map[string]any)
			commands := []any{entry["command"]}
			if inner := toList(entry["hooks"]); inner != nil {
				commands = nil
				for _, h := range inner {
					commands = append(commands, h.(map[string]any)["command"])
				}
			}
			for _, c := range commands {
				if text, _ := c.(string); strings.Contains(text, "_internal ") {
					out = append(out, event+": "+text[strings.Index(text, "_internal ")+len("_internal "):])
				}
			}
		}
	}
	sort.Strings(out)
	return out
}

func readJSON(t *testing.T, path string) map[string]any {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatal(err)
	}
	return m
}

// A plugin must run exactly the hooks `cully setup` installs, or the two
// install paths would behave differently.
func TestPluginHooksMatchWhatSetupInstalls(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("CLAUDE_CONFIG_DIR", filepath.Join(home, ".claude"))
	t.Setenv("CODEX_HOME", filepath.Join(home, ".codex"))
	t.Setenv("CURSOR_CONFIG_DIR", filepath.Join(home, ".cursor"))
	for _, install := range []func() error{installClaude, installCodex, installCursor} {
		if err := install(); err != nil {
			t.Fatal(err)
		}
	}
	root := repoRoot(t)
	for _, c := range []struct{ agent, installed, plugin string }{
		{"claude", filepath.Join(home, ".claude", "settings.json"), "plugins/claude/hooks/hooks.json"},
		{"codex", filepath.Join(home, ".codex", "hooks.json"), "plugins/codex/hooks/hooks.json"},
		{"cursor", filepath.Join(home, ".cursor", "hooks.json"), "plugins/cursor/hooks/hooks.json"},
	} {
		want := hookSubcommands(t, readJSON(t, c.installed))
		got := hookSubcommands(t, readJSON(t, filepath.Join(root, c.plugin)))
		if len(want) == 0 || strings.Join(got, "\n") != strings.Join(want, "\n") {
			t.Errorf("%s plugin hooks differ from setup\nsetup:  %q\nplugin: %q", c.agent, want, got)
		}
	}
}

// Claude Code can validate its own plugin format, which is the authoritative check.
func TestClaudeValidatesThePluginAndMarketplace(t *testing.T) {
	claude, err := exec.LookPath("claude")
	if err != nil {
		t.Skip("claude CLI not installed")
	}
	root := repoRoot(t)
	for _, dir := range []string{filepath.Join(root, "plugins", "claude"), root} {
		out, err := exec.Command(claude, "plugin", "validate", dir).CombinedOutput()
		if err != nil || !strings.Contains(string(out), "Validation passed") {
			t.Errorf("claude plugin validate %s: %v\n%s", dir, err, out)
		}
	}
}
